# CODEFORGE UI PLACEMENT + MAXIMIZE PATCH 007
# FRONTEND ONLY.
# Does NOT modify backend, API keys, provider configuration, API endpoints,
# Copilot request payloads, or Copilot response parsing.
#
# Improvements:
# - Theme toggle is integrated into real page headers instead of floating over every page
# - App pages: theme toggle sits in the authenticated topbar actions
# - Landing: theme toggle sits inside landing navigation actions
# - Login/Register: theme toggle sits beside "Back to landing"
# - Copilot maximize becomes a centered desktop workspace with proper content width
# - Maximized messages/composer are constrained for readability
# - Floating Copilot launcher is hidden while maximized
# - Maximize/restore control uses a proper window icon
# - Mobile maximize gets its own full-screen-safe layout
#
# Run from CodeForge project root OR frontend folder.

$ErrorActionPreference = "Stop"

$Here = (Get-Location).Path

if (Test-Path (Join-Path $Here "src\lib\components\AIAssistant.svelte")) {
    $Frontend = $Here
    $Project = Split-Path $Here -Parent
} elseif (Test-Path (Join-Path $Here "frontend\src\lib\components\AIAssistant.svelte")) {
    $Project = $Here
    $Frontend = Join-Path $Here "frontend"
} else {
    throw "CodeForge frontend not found. Run this patch from the project root or frontend folder."
}

$Files = @{
    Assistant = Join-Path $Frontend "src\lib\components\AIAssistant.svelte"
    ThemeToggle = Join-Path $Frontend "src\lib\components\ThemeToggle.svelte"
    AppShell = Join-Path $Frontend "src\lib\components\AppShell.svelte"
    Landing = Join-Path $Frontend "src\routes\+page.svelte"
    Login = Join-Path $Frontend "src\routes\login\+page.svelte"
    Register = Join-Path $Frontend "src\routes\register\+page.svelte"
    RootLayout = Join-Path $Frontend "src\routes\+layout.svelte"
    AppCss = Join-Path $Frontend "src\app.css"
}

foreach ($Path in $Files.Values) {
    if (!(Test-Path $Path)) {
        throw "Required frontend file not found: $Path"
    }
}

# Guard: this patch is designed to refine PATCH-006, not replace an unknown Copilot implementation.
$CurrentAssistant = [System.IO.File]::ReadAllText($Files.Assistant, [System.Text.Encoding]::UTF8)
if ($CurrentAssistant -notmatch "/api/assistant/chat" -or
    $CurrentAssistant -notmatch "class:maximized" -or
    $CurrentAssistant -notmatch 'maxlength="12000"' -or
    $CurrentAssistant -notmatch "data.reply") {
    throw "Current AIAssistant.svelte does not match the working PATCH-006 Copilot. No files were changed."
}

$CurrentTheme = [System.IO.File]::ReadAllText($Files.ThemeToggle, [System.Text.Encoding]::UTF8)
if ($CurrentTheme -notmatch "position: fixed" -or $CurrentTheme -notmatch "codeforge-theme") {
    throw "Current ThemeToggle.svelte does not match PATCH-006. No files were changed."
}

$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDir = Join-Path $Project "patch-backups\PATCH-007-UI-PLACEMENT-$Stamp"
New-Item -ItemType Directory -Path $BackupDir -Force | Out-Null

$Backups = @{}

function Backup-File([string]$Path) {
    $Relative = $Path.Substring($Frontend.Length).TrimStart('\')
    $SafeName = $Relative -replace '[\\/:*?"<>|]', '__'
    $Backup = Join-Path $BackupDir $SafeName
    Copy-Item $Path $Backup -Force
    $script:Backups[$Path] = $Backup
    Write-Host "[OK] backup: $Relative"
}

function Restore-Backups {
    foreach ($Path in $script:Backups.Keys) {
        $Backup = $script:Backups[$Path]
        if (Test-Path $Backup) {
            Copy-Item $Backup $Path -Force
        }
    }
}

function Write-Base64File([string]$Path, [string]$Data) {
    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($Data))
}

try {
    foreach ($Path in $Files.Values) {
        Backup-File $Path
    }

    Write-Base64File $Files.Assistant ""
    Write-Base64File $Files.ThemeToggle ""
    Write-Base64File $Files.AppShell ""
    Write-Base64File $Files.Landing ""
    Write-Base64File $Files.Login ""
    Write-Base64File $Files.Register ""
    Write-Base64File $Files.RootLayout "PHNjcmlwdCBsYW5nPSJ0cyI+CiAgaW1wb3J0ICcuLi9hcHAuY3NzJzsKPC9zY3JpcHQ+Cgo8c2xvdCAvPgo="
    Write-Base64File $Files.AppCss ""

    Write-Host "[OK] Theme toggle moved into page headers"
    Write-Host "[OK] Copilot maximize layout optimized"
    Write-Host "[OK] Copilot maximize/restore control optimized"
    Write-Host "[OK] Backend/API files untouched"

    foreach ($Generated in @((Join-Path $Frontend ".svelte-kit"), (Join-Path $Frontend "build"))) {
        if (Test-Path $Generated) {
            Remove-Item $Generated -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    Push-Location $Frontend
    try {
        $Npm = Get-Command npm -ErrorAction SilentlyContinue
        if ($Npm) {
            Write-Host "[CHECK] npm run check"
            & npm run check
            if ($LASTEXITCODE -ne 0) {
                throw "npm run check failed"
            }

            Write-Host "[CHECK] npm run build"
            & npm run build
            if ($LASTEXITCODE -ne 0) {
                throw "npm run build failed"
            }
        } else {
            Write-Host "[WARN] npm not found; frontend validation skipped."
        }
    }
    finally {
        Pop-Location
    }

    Write-Host ""
    Write-Host "[SUCCESS] PATCH-007 completed."
    Write-Host "No backend/API files were modified."
    Write-Host ""
    Write-Host "Restart frontend:"
    Write-Host "  cd `"$Frontend`""
    Write-Host "  npm run dev -- --host 127.0.0.1"
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    Restore-Backups
    Write-Host "[ROLLBACK] Original PATCH-006 frontend files restored."
    exit 1
}
